      "comment": "【12月年末輸入限定名牝】輸入繁殖牝馬が充実している。 ワキア （ サイレンススズカ の母）、 バレークイーン （ フサイチコンコルド などの母）は、ともに仔出し10の繁殖牝馬。 バレークイーン は、仔出し10に加えてスタミナ因子も持っており、3頭の銀札史実馬を産む。自身も3歳と若く、 仔出し10の期間も長いので金のお守りに余裕があるなら購入したい。 ワキア は、 サイレンススズカ を自家生産馬にしたいならここで購入しておこう。 輸入種付け馬の ダンシングブレーブ は、後に虹札馬 イクイノックス の母父となる銅札馬 キングヘイロー の父となるため、虹札扱いになっているだけ。スルーでOK。"
